from PIL import Image, ImageDraw, ImageFont
from datetime import datetime
import io
import base64

IMG_B64 = """"""

def handler(request):
    img_data = base64.b64decode(IMG_B64)
    img = Image.open(io.BytesIO(img_data))
    draw = ImageDraw.Draw(img)
    
    font_big = ImageFont.truetype("/usr/share/fonts/truetype/dejavu/DejaVuSerif-Bold.ttf", 56)
    font_small = ImageFont.truetype("/usr/share/fonts/truetype/dejavu/DejaVuSerif.ttf", 13)
    color = (139, 58, 58)
    
    event = datetime(2026, 8, 14, 14, 0, 0)
    delta = event - datetime.now()
    
    j = int(delta.total_seconds() // 86400) if delta.total_seconds() > 0 else 0
    h = int((delta.total_seconds() % 86400) // 3600) if delta.total_seconds() > 0 else 0
    m = int((delta.total_seconds() % 3600) // 60) if delta.total_seconds() > 0 else 0
    s = int(delta.total_seconds() % 60) if delta.total_seconds() > 0 else 0
    
    txt = f"{j:02d}:{h:02d}:{m:02d}:{s:02d}"
    
    draw.text((1020, 150), txt, fill=color, font=font_big)
    draw.text((980, 220), "JOURS", fill=color, font=font_small)
    draw.text((1070, 220), "HEURES", fill=color, font=font_small)
    draw.text((1160, 220), "MINUTES", fill=color, font=font_small)
    draw.text((1250, 220), "SECONDES", fill=color, font=font_small)
    
    buf = io.BytesIO()
    img.save(buf, format="PNG")
    buf.seek(0)
    
    return {
        "statusCode": 200,
        "headers": {"Content-Type": "image/png", "Cache-Control": "max-age=1"},
        "body": base64.b64encode(buf.getvalue()).decode(),
        "isBase64Encoded": True
    }
